'use client';

import type { JSX, ReactNode } from 'react';
import {
  Collection,
  Header,
  Keyboard,
  Menu as RACMenu,
  MenuItem as RACMenuItem,
  MenuSection as RACMenuSection,
  PopoverContext,
  Separator,
  Text,
  composeRenderProps,
  useSlottedContext,
  type MenuItemProps as RACMenuItemProps,
  type MenuProps as RACMenuProps,
  type MenuSectionProps as RACMenuSectionProps,
  type SeparatorProps,
} from 'react-aria-components';
import { IconCheck, IconChevronRight } from '@tabler/icons-react';
import { Popover, type PopoverProps } from './popover';
import styles from './menu.module.css';

export {
  MenuTrigger,
  SubmenuTrigger,
  type MenuTriggerProps,
  type SubmenuTriggerProps,
} from 'react-aria-components';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

export interface MenuProps<T> extends RACMenuProps<T> {
  /** Where the menu opens relative to its trigger. Defaults to below, aligned to the start edge; submenus open at the end edge. */
  placement?: PopoverProps['placement'];
}

/**
 * A list of actions or options. Inside a MenuTrigger (or as the second child of a SubmenuTrigger) it renders in a
 * popover anchored to the trigger; anywhere else it renders inline.
 */
export function Menu<T extends object>({ className, placement, ...props }: MenuProps<T>): JSX.Element {
  const trigger = useSlottedContext(PopoverContext)?.trigger;
  const menu = <RACMenu<T> {...props} className={composeRenderProps(className, (c) => cx(styles.menu, c))} />;
  if (trigger === 'MenuTrigger') {
    return (
      <Popover className={styles.popover} {...(placement && { placement })}>
        {menu}
      </Popover>
    );
  }
  if (trigger === 'SubmenuTrigger') {
    // Line the submenu's first item up with the item that opened it, a few px clear of the parent menu.
    return (
      <Popover className={styles.popover} offset={8} crossOffset={-5} {...(placement && { placement })}>
        {menu}
      </Popover>
    );
  }
  return menu;
}

export interface MenuItemProps<T = object> extends Omit<RACMenuItemProps<T>, 'children'> {
  /** The item's label. */
  children: ReactNode;
  /** Leading icon, e.g. `<IconPencil />`. Decorative — the label names the item. */
  icon?: ReactNode;
  /** Secondary line under the label. */
  description?: ReactNode;
  /** Keyboard shortcut hint shown at the inline end, e.g. "⌘E". Display only — bind the keys yourself. */
  shortcut?: string;
  /** `danger` marks destructive actions. */
  tone?: 'neutral' | 'danger';
}

/** One action or option in a Menu. */
export function MenuItem<T extends object>({
  children,
  icon,
  description,
  shortcut,
  tone = 'neutral',
  textValue,
  className,
  ...props
}: MenuItemProps<T>): JSX.Element {
  return (
    <RACMenuItem<T>
      {...props}
      textValue={textValue ?? (typeof children === 'string' ? children : undefined)}
      data-tone={tone === 'danger' ? tone : undefined}
      className={composeRenderProps(className, (c) => cx(styles.item, c))}
    >
      {({ hasSubmenu, isSelected, selectionMode }) => (
        <>
          {selectionMode !== 'none' && (
            <span className={styles.check} aria-hidden>
              {isSelected && <IconCheck size="1em" stroke={2} />}
            </span>
          )}
          {icon != null && (
            <span className={styles.icon} aria-hidden>
              {icon}
            </span>
          )}
          <span className={styles.text}>
            <Text slot="label" className={styles.label}>
              {children}
            </Text>
            {description != null && (
              <Text slot="description" className={styles.description}>
                {description}
              </Text>
            )}
          </span>
          {shortcut && <Keyboard className={styles.shortcut}>{shortcut}</Keyboard>}
          {hasSubmenu && <IconChevronRight className={styles.chevron} aria-hidden size="1em" stroke={1.75} />}
        </>
      )}
    </RACMenuItem>
  );
}

export interface MenuSectionProps<T> extends RACMenuSectionProps<T> {
  /** Visible heading for the group; also its accessible name. */
  title?: ReactNode;
}

/** Groups related items under an optional heading. */
export function MenuSection<T extends object>({
  title,
  items,
  children,
  className,
  ...props
}: MenuSectionProps<T>): JSX.Element {
  return (
    <RACMenuSection<T> {...props} className={cx(styles.section, className)}>
      {title != null && <Header className={styles.sectionTitle}>{title}</Header>}
      {typeof children === 'function' ? <Collection items={items}>{children}</Collection> : children}
    </RACMenuSection>
  );
}

export type MenuSeparatorProps = SeparatorProps;

/** A hairline between groups of items. */
export function MenuSeparator({ className, ...props }: MenuSeparatorProps): JSX.Element {
  return <Separator {...props} className={cx(styles.separator, className)} />;
}

.popover {
  --popover-padding: var(--strata-space-1);
  display: flex;
  flex-direction: column;
}

.menu {
  box-sizing: border-box;
  min-inline-size: max(var(--trigger-width, var(--strata-space-0)), calc(var(--strata-space-16) * 2.5));
  flex: 1 1 auto;
  min-block-size: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  outline: none;
}
/* Programmatic focus on open. Pseudo-class selector so page-level `[tabindex]:focus-visible` rules can't outrank it. */
.menu:focus-visible {
  outline: none;
}

.item {
  --menu-item-radius: min(var(--strata-radius-button), var(--strata-space-2));
  position: relative;
  display: flex;
  align-items: center;
  gap: var(--strata-space-2);
  min-block-size: calc(var(--strata-control-height) - var(--strata-space-2));
  padding: var(--strata-space-1) var(--strata-space-2);
  border-radius: var(--menu-item-radius);
  color: var(--strata-color-text-default);
  font-size: var(--strata-font-size-md);
  line-height: var(--strata-line-height-snug);
  text-decoration: none;
  cursor: default;
  user-select: none;
  outline: none;
  -webkit-tap-highlight-color: transparent;
}
.item[data-focused],
.item[data-open] {
  background: color-mix(in oklab, var(--strata-color-text-default) 6%, transparent);
}
.item[data-pressed] {
  background: color-mix(in oklab, var(--strata-color-text-default) 10%, transparent);
}
/* Neutralise page-level `[tabindex]:focus-visible` rules; the ring below is the item's focus indicator. */
.item:focus-visible {
  outline: none;
  border-radius: var(--menu-item-radius);
}
.item[data-focus-visible] {
  outline: 2px solid var(--strata-color-focus-ring);
  outline-offset: -2px;
}
.item[data-tone='danger'] {
  color: var(--strata-color-feedback-danger-fg);
}
.item[data-tone='danger'][data-focused] {
  background: color-mix(in oklab, var(--strata-color-feedback-danger-solid) 10%, transparent);
}
.item[data-disabled] {
  color: var(--strata-color-text-disabled);
  pointer-events: none;
}
.item[href] {
  cursor: pointer;
}

.check,
.icon {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  inline-size: 1.125em;
  block-size: 1.125em;
}
.check {
  color: var(--strata-color-text-default);
}
.icon {
  color: var(--strata-color-text-subtle);
}
.icon svg {
  inline-size: 100%;
  block-size: 100%;
}
.item[data-tone='danger'] .icon {
  color: currentColor;
}
.item[data-disabled] .icon,
.item[data-disabled] .check {
  color: var(--strata-color-text-disabled);
}

.text {
  display: grid;
  flex: 1 1 auto;
  min-inline-size: 0;
}
.label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.description {
  font-size: var(--strata-font-size-xs);
  line-height: var(--strata-line-height-normal);
  color: var(--strata-color-text-subtle);
}
.item[data-disabled] .description {
  color: var(--strata-color-text-disabled);
}

.shortcut {
  flex: none;
  margin-inline-start: auto;
  padding-inline-start: var(--strata-space-4);
  font-family: var(--strata-font-body);
  font-size: var(--strata-font-size-xs);
  font-variant-numeric: tabular-nums;
  color: var(--strata-color-text-subtle);
}
.item[data-disabled] .shortcut {
  color: var(--strata-color-text-disabled);
}

.chevron {
  flex: none;
  margin-inline-start: auto;
  color: var(--strata-color-text-subtle);
}
/* The popover root always carries dir. Kept apart from :dir() (which some CSS pipelines rewrite to :lang()). */
.popover[dir='rtl'] .chevron {
  scale: -1 1;
}
.chevron:dir(rtl) {
  scale: -1 1;
}

.section:not(:first-child) {
  margin-block-start: var(--strata-space-1);
}
.sectionTitle {
  padding: var(--strata-space-1) var(--strata-space-2);
  font-size: var(--strata-font-size-xs);
  font-weight: var(--strata-font-weight-medium);
  line-height: var(--strata-line-height-normal);
  color: var(--strata-color-text-subtle);
}

.separator {
  block-size: 1px;
  margin-block: var(--strata-space-1);
  margin-inline: calc(var(--strata-space-1) * -1);
  border: 0;
  background: var(--strata-color-border-subtle);
}
